                key={`${stringItem}${index}`}
                {...getItemProps({item, index, disabled: item.disabled})}
              >
                {stringItem}
              </li>
            )
          })}
      </ul>
    </div>
  )
}

const renderUseCombobox = props => {
  return renderHook(() => useCombobox({items, ...props}))
}

